      (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) ||                                                       // PNG
      (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46) ||                                                                        // GIF
      (b[0] === 0x42 && b[1] === 0x4d) ||                                                                                         // BMP
      (n >= 12 && b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 && b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50) // WEBP (RIFF....WEBP)
