      if (raw.length > recs.length * 2 + 20) { writeJsonlFile(file, keep); logEvent("harvested_products_compacted", { fileLinesBefore: raw.length, unique: recs.length }); }
      return { ok: true, prunedCount: 0, keptCount: keep.length };
