function autoEnableAdminApprovalIfPersistentFailures(groupUrl) {
  const targetKey = normalizedFacebookGroupKey(groupUrl);
  if (!targetKey) return false;
  let ledgerEntries = [];
  try { ledgerEntries = readJsonlAbsoluteFile(FB_LIVE_POST_LEDGER_FILE, { limit: 500 }); } catch {}
  const cutoff = Date.now() - 24 * 60 * 60 * 1000;
  const recentUncertain = ledgerEntries.filter((item) => {
    if (!item) return false;
    const itemGroupKey = normalizedFacebookGroupKey(item.groupUrl || item.actualGroupUrl || "");
    if (itemGroupKey !== targetKey) return false;
    const atMs = Date.parse(item.at || 0);
    if (!Number.isFinite(atMs) || atMs < cutoff) return false;
    const status = String(item.status || "").toLowerCase();
    const event = String(item.event || "").toLowerCase();
    return /uncertain_after_post_click/.test(status) || /uncertain_after_click/.test(event);
  });
  // THRESHOLD 2->1 (2026-07-03, operator: "he should work smoothly with any number of groupes and profiles").
  // Measured live: a brand-new group ran for ~2.5-3h with admin-approval NOT actually active (this reactive
  // self-heal is the ONLY thing that turns it on when the operator's initial config lags Facebook's true setting),
  // during which ~26 posts on that group were tried by 8 different profiles and permanently abandoned because the
  // moderator-rescue path was gated off. Reacting on the FIRST uncertain-after-click signal instead of waiting for
  // a 2nd occurrence cuts that detection window substantially for any newly-added group, at low risk: this only
  // flips requiresAdminApproval from false->true (never disables it), and a group that genuinely doesn't need
  // moderation would need a false "uncertain_after_post_click" signal to mis-fire even once.
  if (recentUncertain.length < 1) return false;
  const stateToUpdate = readState();
  let changed = false;
  for (const g of (Array.isArray(stateToUpdate.posting?.groupAssignmentData) ? stateToUpdate.posting.groupAssignmentData : [])) {
    if (normalizedFacebookGroupKey(g?.url) === targetKey && !g.requiresAdminApproval) {
      g.requiresAdminApproval = true;
      changed = true;
    }
  }
  if (!changed) return false;
  try {
    writeState(stateToUpdate);
    logEvent("facebook_group_auto_flagged_requires_admin_approval", {
      groupUrl,
      recentUncertainCount: recentUncertain.length,
      reason: "post_submitted_but_permalink_not_captured_repeatedly",
    });
    return true;
  } catch (err) {
    logEvent("facebook_group_auto_flag_failed", { groupUrl, error: oneLineField(err.message || String(err), 200) });
    return false;
  }
}

// Serialize moderator-approval sessions PER MODERATOR PROFILE, not box-wide (2026-07-03, operator: "why does he
// sometimes break for 1 hour" -- traced live: facebook_admin_approval_lock_acquired queueWaitMs up to ~707s (11.8min),
// stacking as each session's own up-to-8min budget blocked EVERY OTHER pending-post approval, producing the 30-60min
// posting gaps he saw). The single global lock chain was built when only 2 shared moderator profiles existed (p41/p42)
// and TWO sessions racing the SAME profile really did collide on iX profile-open. With 4 distinct moderators now
// configured, that global serialization is unnecessary: keying the lock per moderator PROFILE ID (not globally) lets
// DIFFERENT moderators approve DIFFERENT pending posts truly in parallel, while a genuine double-open of the SAME
// profile still serializes correctly. Existing CPU/RAM guards (adaptive concurrency, GLOBAL_MAX_OPEN_PROFILES,
