      ok: false,
      profileId: numericProfileId,
      profile: cleanProfile,
      validation,
      closeResults,
      message: `IXBrowser profile "${cleanProfile}" is not attributed to this group; it will not comment here.`,
      liveLog: [],
      liveLogFile: "",
